// A Tinta film as data: which objects exist and where they stand, which shots cut the narration, and what happens when.
// A model writes names (objects, scenery, places, actions); code turns them into positions, cameras and timing.

export const FPS = 30;

// Where an object stands: one of the named places of a scenery template (see escenarios.ts).
export type Lugar = {escenario: string; slot: string};

// fuente: 'kenney:<pack>/<model>' (catalogue model), 'glb:<file under public/>' (generated by TRELLIS), 'bolo' (the stock
// character), 'pelota' (a red ball) or 'construccion:<id>' (built in code from `partes`, see construcciones.ts; `largo` is ignored).
export type Objeto = {id: string; nombre: string; fuente: string; largo: number; lugar: Lugar; contorno?: boolean; giro?: number; partes?: string[]};

// Things that happen, in film seconds. Objects with an 'aparece' are hidden until it, and after a 'desaparece' they are
// gone; 'entra' walks from the scenery's door.
export type Accion =
	| {tipo: 'aparece'; objeto: string; en: number}
	| {tipo: 'desaparece'; objeto: string; en: number}
	| {tipo: 'pulso'; objeto: string; en: number; hasta: number}
	| {tipo: 'cono'; objeto: string; en: number; hasta: number; hacia: string}
	| {tipo: 'entra'; objeto: string; en: number; hasta: number}
	| {tipo: 'gira'; objeto: string; en: number; hasta: number}
	| {tipo: 'falla'; objeto: string; en: number; hasta: number; efecto: string}
	| {tipo: 'cae'; objeto: string; en: number; hasta: number}
	| {tipo: 'lluvia'; objeto: string; en: number; hasta: number};

export type Tono = 'normal' | 'alerta' | 'info';

// How a shot comes in. golpe: from closer up, settling; latigo: a fast sideways pan; destello: a flash.
export const ENTRADAS = {corte: 0, golpe: 0.2, latigo: 0.24, destello: 0.3} as const;
export type Entrada = keyof typeof ENTRADAS;

// A shot: a stretch of the film seen from one camera. 'general' shows the whole scenery, 'objeto' frames one object.
// entrada is optional: without it, entradaDe decides from what changes at the cut.
// campana: the caption comes in with the chime; without it, a caption that carries a figure does.
export type Toma = {desde: number; hasta: number; escenario: string; encuadre: 'general' | 'objeto'; objetivo?: string; rotulo?: string; tono?: Tono; entrada?: Entrada; campana?: boolean};

export type Pelicula = {nombre: string; duracion: number; objetos: Objeto[]; tomas: Toma[]; acciones: Accion[]; audio?: string | null};

// falla: a construction fails (efecto from FALLAS in construcciones.ts); cae: an object drops from its place to the ground;
// lluvia: rain over the shots of the object's scenery.
export const TIPOS_ACCION = ['aparece', 'desaparece', 'pulso', 'cono', 'entra', 'gira', 'falla', 'cae', 'lluvia'] as const;

export const tomaEn = (p: Pelicula, t: number) => p.tomas.find((s) => t >= s.desde && t < s.hasta) ?? p.tomas[p.tomas.length - 1];

// The way shot i comes in, when the film does not say: a whip pan to another scenery, a flash when the alert starts,
// a punch-in when the camera goes to an object of the same scenery, and a plain cut otherwise.
export const entradaDe = (p: Pelicula, i: number): Entrada => {
	const t = p.tomas[i];
	const a = p.tomas[i - 1];
	if (!a) return 'corte';
	if (t.entrada) return t.entrada;
	if (t.escenario !== a.escenario) return 'latigo';
	if (t.tono === 'alerta' && a.tono !== 'alerta') return 'destello';
	if (t.encuadre === 'objeto' && (a.encuadre !== 'objeto' || a.objetivo !== t.objetivo)) return 'golpe';
	return 'corte';
};
